      idName: resultsListId,
      className: resultsListClass,
      navigation,
    };
    this.sort = sort;
    this.placeHolder = placeHolder;
    this.maxResults = maxResults;
    this.resultItem = {
      content,
      element: resultItemElement,
      idName: resultItemId,
      className: resultItemClass,
    };
    this.noResults = noResults;
    this.highlight = highlight;
    this.feedback = feedback;
    this.onSelection = onSelection;
    this._navigateListener = null;
    // Invoking preInit if enabled
    // or initiate autoComplete instance directly
    this.observer ? this.preInit() : this.init();"
    },
    {
      "path": "src/autoComplete.js",
      "sha256": "0d0d446adae1a014da3d8ab13ee99cb73e0094218b8a48458756f2145b850fea",
      "before": "  start(input, query) {
    // - Match query with existing value
    // Returns matching results list
    const results = this.data.results
      ? this.data.results(listMatchingResults(this, query))
      : listMatchingResults(this, query);
    // - Prepare data feedback object
    const dataFeedback = { input, query, matches: results, results: results.slice(0, this.maxResults) };
    /**
     * @emits {response} Emits Event on search response
     **/
    eventEmitter(this.inputField, dataFeedback, "response");
    // - Checks if there are NO results
    // Runs noResults action function
    if (!results.length) return this.noResults ? this.noResults(dataFeedback, generateList) : null;
    // - If resultsList set not to render
    if (!this.resultsList.render) return this.feedback(dataFeedback);
    // - Generate & Render results list
    const list = results.length ? generateList(this, dataFeedback, results) : null;
    /**
     * @emits {rendered} Emits Event after results list rendering
     **/
    eventEmitter(this.inputField, dataFeedback, "rendered");
    // - Initialize navigation
    navigate(this, dataFeedback);
  }",
      "after": "  start(input, query) {
    // - Match query with existing value
    // Returns matching results list
    const results = this.data.results
      ? this.data.results(listMatchingResults(this, query))
      : listMatchingResults(this, query);
    // - Prepare data feedback object
    const dataFeedback = { input, query, matches: results, results: results.slice(0, this.maxResults) };
    /**
     * @emits {response} Emits Event on search response
     **/
    eventEmitter(this.inputField, dataFeedback, "response");
    // - Checks if there are NO results
    // Runs noResults action function
    if (!results.length) return this.noResults ? this.noResults(dataFeedback, generateList) : null;
    // - If resultsList set not to render
    if (!this.resultsList.render) return this.feedback(dataFeedback);
    // - Generate & Render results list
    const list = results.length ? generateList(this, dataFeedback, results) : null;
    /**
     * @emits {rendered} Emits Event after results list rendering
     **/
    eventEmitter(this.inputField, dataFeedback, "rendered");
    // - Initialize navigation
    const nav = navigate(this, dataFeedback);
    if (this._navigateListener) {
      this.inputField.removeEventListener("keydown", this._navigateListener);
    }
    this._navigateListener = nav;
    this.inputField.addEventListener("keydown", nav);
  }"
    }
  ],
  "expected_accessibility_effect": "Keyboard navigation of the combobox will work reliably: arrow keys will move focus among options with correct aria-selected and aria-activedescendant updates, and Enter will select the currently highlighted option. Duplicate listeners that could interfere with assistive technology or cause inconsistent states are eliminated.",
  "functional_risks": [
    "Removing the navigation listener could inadvertently remove a listener added by external code if they relied on the same signature, but the listener is internal to the component.",
    "If the instance is destroyed via `unInit`, the stored listener reference is not cleaned up, potentially causing a memory leak; however, the listener is removed from the input field when replaced, and the reference will be garbage‑collected when the instance is discarded.",
    "Changing the listener management timing could affect edge cases where rapid input changes cause frequent listener replacement; however, the debounce and existing logic already limit frequency."
  ],
  "verification_requirements": [
    "After the sequence 'b', ArrowDown, ArrowDown, 'l', ArrowDown, Enter, the input value must be 'Blackberry'.",
    "Verify that aria-activedescendant updates correctly on each ArrowDown and that the correct option receives aria-selected='true'.",
    "Confirm that the list opens on input and closes after selection or Esc.",
    "Ensure no duplicate keydown listeners are attached to the input field (e.g., by checking listener count or using getEventListeners in devtools).",
    "Regression guard: typing 'bl', ArrowDown, ArrowDown, Enter should result in 'Blackcurrant' (second suggestion)."
  ]
}
